export async function sumAsyncInvoices(invoices: {
    qty: number;
    unitCents: number;
}[]) {
    const cents = await Promise.all(invoices.map(async (invoice) => { const x = await Promise.resolve(invoice); return x.qty * x.unitCents; }));
    return cents.reduce((sum, n) => sum + n, 0);
}
